input.content:
$root = 'C:\Users\eric_rash\Desktop\DEV'
$skip = @('.claude','_tools','_DRIVE','token-dashboard')
$dirs = @()
$dirs += Get-ChildItem $root -Directory -Force
foreach ($sub in 'Football','SpecialRequests') {
  if (Test-Path "$root\$sub") { $dirs += Get-ChildItem "$root\$sub" -Directory -Force }
}
$rows = foreach ($d in $dirs) {
  if ($skip -contains $d.Name -or $d.Name -like '*_OLD_merged*' -or $d.Name -like '.*') { continue }
  $p = $d.FullName
  $rel = $p.Substring($root.Length + 1)
  if (-not (Test-Path "$p\.git")) { [pscustomobject]@{rel=$rel;state='NOT_REPO';remote='';dirty=0;ahead=0;behind=0;branch=''}; continue }
  $remote = git -C $p remote get-url origin 2>$null
  if (-not $remote) { [pscustomobject]@{rel=$rel;state='NO_REMOTE';remote='';dirty=(git -C $p status --porcelain | Measure-Object).Count;ahead=0;behind=0;branch=''}; continue }
  git -C $p fetch -q origin 2>$null
  $br = git -C $p rev-parse --abbrev-ref HEAD
  $dirty = (git -C $p status --porcelain | Measure-Object).Count
  $ab = git -C $p rev-list --left-right --count "HEAD...origin/$br" 2>$null
  $a=0;$b=0; if ($ab) { $parts = $ab -split '\s+'; $a=[int]$parts[0]; $b=[int]$parts[1] }
  [pscustomobject]@{rel=$rel;state='REPO';remote=$remote;dirty=$dirty;ahead=$a;behind=$b;branch=$br}
}
$rows | Export-Csv "$PSScriptRoot\inventory.csv" -NoTypeInformation
"total: $($rows.Count)"
"not repo: " + (($rows | ? state -eq 'NOT_REPO' | % rel) -join ', ')
"no remote: " + (($rows | ? state -eq 'NO_REMOTE' | % rel) -join ', ')
"non-erash11 remote: " + (($rows | ? {$_.state -eq 'REPO' -and $_.remote -notmatch 'erash11'} | % {"$($_.rel)=$($_.remote)"}) -join ', ')
"non-main branch: " + (($rows | ? {$_.state -eq 'REPO' -and $_.branch -notin 'main','master'} | % {"$($_.rel)=$($_.branch)"}) -join ', ')
"needs action:"
$rows | ? {$_.dirty -gt 0 -or $_.ahead -gt 0 -or $_.behind -gt 0} | Format-Table rel,branch,dirty,ahead,behind -AutoSize | Out-String -Width 200
$names = $rows | % { Split-Path $_.rel -Leaf }
$gh = (gh repo list erash11 --limit 300 --json name | ConvertFrom-Json).name
$ghskip = 'dotclaude','SecondBrain','claude-skills','claude-memory-compiler','DEV','DexaProject'
"missing locally: " + (($gh | ? { $_ -notin $names -and $_ -notin $ghskip }) -join ', ')

