$r='C:\Users\eric_rash\Desktop\DEV'
foreach ($n in '_INBOX','DataBase_GPS_Reporting') {
  $p="$r\$n"; $gi="$p\.gitignore"
  if (-not (Select-String -Path $gi -Pattern '^\.claude/worktrees/?$' -Quiet -ErrorAction SilentlyContinue)) { Add-Content -Path $gi -Value "`n# Claude Code worktrees (nested git checkouts)`n.claude/worktrees/" }
  git -C $p add .gitignore; git -C $p commit -q -m "windows snapshot before sync: ignore .claude/worktrees" 2>&1 | Select-Object -Last 1
  "$n dirty after: $((git -C $p status --porcelain | Measure-Object).Count)"
  "$n worktrees:"; git -C $p worktree list
}
foreach ($n in '_INBOX','DataBase_GPS_Reporting','ForcePlate_DecisionSystem','PlayerProfiles_FB_03-28-2026','claude-global-memory') {
  $p="$r\$n"; $br = git -C $p rev-parse --abbrev-ref HEAD
  "=== $n"
  git -C $p fetch -q origin
  git -C $p merge --no-edit "origin/$br" 2>&1 | Select-Object -Last 2
  git -C $p push -q 2>&1 | Select-Object -Last 2
  git -C $p rev-list --left-right --count "HEAD...origin/$br"
}

